export function parseDuration(s) {
  if (typeof s !== 'string' || s.trim() === '') {
    throw new TypeError('Input must be a non‑empty string');
  }

  // Pattern: optional hours, optional minutes, optional seconds, in that order.
  const regex = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/i;
  const match = s.match(regex);

  if (!match) {
    throw new Error(`Invalid duration format: "${s}"`);
  }

  const [, hStr, mStr, sStr] = match;
  // At least one unit must be present
  if (hStr === undefined && mStr === undefined && sStr === undefined) {
    throw new Error(`Duration must contain at least one unit: "${s}"`);
  }

  const hours   = hStr !== undefined ? Number(hStr) : 0;
  const minutes = mStr !== undefined ? Number(mStr) : 0;
  const seconds = sStr !== undefined ? Number(sStr) : 0;

  // Basic sanity check: all parts must be non‑negative integers
  if (![hours, minutes, seconds].every(v => Number.isInteger(v) && v >= 0)) {
    throw new Error(`Duration units must be non‑negative integers: "${s}"`);
  }

  return hours * 3600 + minutes * 60 + seconds;
}
