export default class LRUCache {
  /**
   * @param {number} capacity - máxima cantidad de entradas que el caché puede contener
   */
  constructor(capacity) {
    if (typeof capacity !== 'number' || capacity <= 0) {
      throw new Error('Capacity must be a positive number');
    }
    this._capacity = capacity;
    // Map mantiene el orden de inserción; al mover una clave la eliminamos y la volvemos a insertar.
    this._cache = new Map();
  }

  /**
   * Obtiene el valor asociado a la clave.
   * @param {*} key
   * @returns {*} valor o -1 si la clave no está presente
   */
  get(key) {
    if (!this._cache.has(key)) return -1;
    const value = this._cache.get(key);
    // Marcar como usado recientemente: eliminar y volver a insertar
    this._cache.delete(key);
    this._cache.set(key, value);
    return value;
  }

  /**
   * Inserta o actualiza el par clave‑valor.
   * Si la capacidad se supera, se elimina la clave menos usada recientemente.
   * @param {*} key
   * @param {*} value
   */
  put(key, value) {
    if (this._cache.has(key)) {
      // Actualizar el valor y mover al final (más reciente)
      this._cache.delete(key);
    }
    this._cache.set(key, value);

    // Si excedemos la capacidad, eliminar la entrada menos reciente (el primer elemento del Map)
    if (this._cache.size > this._capacity) {
      const lruKey = this._cache.keys().next().value;
      this._cache.delete(lruKey);
    }
  }
}
