export function longestCommonPrefix(strs) {
  if (!Array.isArray(strs) || strs.length === 0) return '';

  // Find the shortest string to limit comparison length
  const minLen = strs.reduce((min, s) => Math.min(min, s.length), Infinity);
  if (minLen === 0) return '';

  let prefix = '';
  for (let i = 0; i < minLen; i++) {
    const char = strs[0][i];
    if (strs.every(s => s[i] === char)) {
      prefix += char;
    } else {
      break;
    }
  }
  return prefix;
}
