    let right = s.length - 1;

    while (left < right) {
        const charLeft = s[left];
        const charRight = s[right];

        if (!isAlphaNumeric(charLeft)) {
            left++;
        } else if (!isAlphaNumeric(charRight)) {
            right--;
        } else {
            if (charLeft.toLowerCase() !== charRight.toLowerCase()) {
