/**
 * Merges an array of intervals, sorting them and combining overlapping or touching intervals.
 * @param {Array<Array<number>>} intervals - An array of [start, end] pairs (unsorted).
 * @returns {Array<Array<number>>} A new array of merged, sorted, non‑overlapping intervals.
 */
export function mergeIntervals(intervals) {
    if (!Array.isArray(intervals) || intervals.length === 0) {
        return [];
    }

    // Clone and sort intervals by start (and by end if starts are equal)
    const sorted = intervals
        .map(pair => {
            const [a, b] = pair;
            // Ensure each interval is [min, max]
            return a <= b ? [a, b] : [b, a];
        })
        .sort((i1, i2) => i1[0] - i2[0] || i1[1] - i2[1]);

    const merged = [];
    let [curStart, curEnd] = sorted[0];

    for (let i = 1; i < sorted.length; i++) {
        const [nextStart, nextEnd] = sorted[i];

        // Overlap or touch: merge
        if (nextStart <= curEnd) {
            curEnd = Math.max(curEnd, nextEnd);
        } else {
            merged.push([curStart, curEnd]);
            [curStart, curEnd] = [nextStart, nextEnd];
        }
    }

    // Push the last interval
    merged.push([curStart, curEnd]);

    return merged;
}
