/**
 * Convert a Roman numeral (1‑3999) to its integer value.
 * @param {string} s - Roman numeral string (uppercase, valid)
 * @returns {number} Integer representation
 */
export function romanToInt(s) {
    const values = {
        I: 1,
        V: 5,
        X: 10,
        L: 50,
        C: 100,
        D: 500,
        M: 1000,
    };

    let total = 0;
    let prev = 0;

    // Iterate from right to left so subtraction cases are easy to detect
    for (let i = s.length - 1; i >= 0; i--) {
        const curr = values[s[i]];
        if (curr < prev) {
            total -= curr; // subtraction case (e.g., IV, IX)
        } else {
            total += curr;
        }
        prev = curr;
    }

    return total;
}
